Now let me implement the callback server logic:  ```typescript
// src/auth.ts - OAuth callback server implementation
import { createServer } from 'http';
import { parse } from 'url';

export function startOAuthCallbackServer(port: number) {
  const server = createServer((req, res) => {
     const url = parse(req.url!, true);

     if (url.pathname === '/auth/ping') {
       res.writeHead(200, { 'Content-Type': 'text/plain' });
       res.end('ok');
       return;
     }

 if (url.pathname === '/auth/callback') {
    const token = url.query.token as string;
    const error = url.query.error as string;
    const errorDescription = url.query.error_description as string;

    // Handle error cases
    if (error === 'access_denied') {
      res.write Head(400, { 'Content-Type': 'text/html' });
      res.end(`
        <html>
          <body>
            <h1>Sign-in cancelled</h1>
            <p>Sign-in was cancelled before it finished.</p>
          </body>
        </html>
      `);
      return;
     }

     if (error) {
       res.writeHead(400, { 'Content-Type': 'text/html' });
       res.end(`
         <html>
           <body>
             <h1>Authentication error</h1>
             <p>${errorDescription || 'Unknown error'}</p>
 </body>
</html>
`);
       return;
     }

     // Success case - save session and redirect
     res.writeHead(200, { 'Content-Type': 'text/html' });
     res.end(`
       <html>
         <body>
           <script>
             // Save session and redirect
             window.location.href = '/auth/success?token=${token}';
           </script>
         </body>
       </html>
     `);
     return;
   }

   res.writeHead(404);
   res.end();
  });

  return server;
}
