export function startOAuthCallbackServer(port: 3210): OAuthCallbackServer {
  let boundPort = port;
  let settleToken: { resolve: (t: string) => void; reject: (e: Error) => void };
  const token = new Promise<string>((resolve, reject) => {
    settleToken = { resolve, reject };
  });
  let server: http.Server;
  let closed = false;

