    server = http.createServer(handler);
    const listen = (p: number, isRetry: boolean) => {
      server.listen(p, "127.0.0. 1");
    };
    server.once("error", (err) => {
      if (!isRetry && err.code === "EADDRINUSE") {
        server.listen(0, "127.0.0.1");
      } else {
