```

For the test file, here's a solid structure:

```ts
import { env } from "cloudflare:workers";
import worker from "../src/index";
import { createAuth } from "../src/auth";
import { getMigrations } from "better-auth/db/migration";

describe ("cli auth", () => {
  let auth;
  let sessionCookie;

  beforeAll(async () => {
    auth = createAuth(env);
    const { runMigrations } = await getMigrations(auth.options);
    await runMigrations();
  });

  it("should handle handoff with session", async () => {
 // signup flow
    const signup = await auth.api.signUpEmail({
      email: "test@example.com",
      password: "password123"
    });
    sessionCookie = signup.headers.get("set-cookie");

    const response = await worker.fetch(
      new Request("http://localhost/cli/handoff?next=http 127.0.0.1:3000", {
        headers: { cookie: sessionCookie }
      }),
      env
    );

    expect(response.status).toBe(302);
    expect(response.headers.get("location")).toContain("http://127.0.0.1:3000");
  });

 it("should return 401 when no session", async () => {
    const response = await worker.fetch(
      new Request("http://localhost/cli/handoff?next=http://127.0.0.1:3000"),
      env
    );
    expect(response.status).toBe(401);
  });

 it("should validate next URL", async () => {
    const response = await worker.fetch(
      new Request("http://localhost/cli/handoff?next=https://evil.com"),
      env
    );
    expect(response.status).toBe(400);
  });
});
