export function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) =>
    ({ "&": "&", "<": "<", ">": ">", '"': "&quot;", "'": "&#39;" })[char]!,
  );
}

function arcadePage(tone: string, title: string, lead: string, steps: string[], hint: string): string {
  const list = steps.length === 0
    ? ""
    : `<ul class="steps">${steps.map((step) => `<li>${step}</li>`).join("")}</ul>`;
  const hintHtml = hint ? `<p class="hint">${hint}</p>` : "";
  const icon = tone === "ok" ? CHECK_ICON : ALERT_ICON;
  const titleText = escapeHtml(title);
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<title>Tui — ${titleText}</title>
<style>${STYLE}</style>
</head>
<body>
<main class="card" data-tone="${tone}">
<span class="badge">${icon}</span>
<p class="eyebrow">Tui</p>
<h1>${titleText}</h1>
<p class="lead">${lead}</p>
${list}
${hintHtml}
</main>
</body>
</html>`;
}

/** Hands the signed-in browser session back to the CLI listener. */
export function handoffRedirectPage(targetUrl: string): string {
  const escaped = escapeHtml(targetUrl);
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<meta http-equiv="refresh" content="0;url=${escaped}">
<meta name="referrer" content="no-referrer">
<title>Tui — Continuing sign-in</title>
<style>${STYLE}</style>
</head>
<body>
<main class="card" data-tone="ok">
<span class="badge">${CHECK_ICON}</span>
<p class="eyebrow">Tui</p>
<h1>Continuing sign-in</h1>
<p class="lead">Sending you back to the terminal. You can close this tab if it does not continue on its own.</p>
<p class="hint"><a href="${escaped}">Continue</a></p>
</main>
<script>location.replace(${JSON.stringify(targetUrl)})</script>
</body>
</html>`;
}

