export function escapeHtml(value: string): string {
  let out = "";
  for (const character of value) {
    switch (character) {
      case "&":
        out += "\u0026amp;";
        break;
      case "<":
        out += "\u0026lt;";
        break;
      case ">":
        out += "\u0026gt;";
        break;
      case '"':
        out += "\u0026quot;";
        break;
      case "'":
        out += "\u0026#39;";
        break;
      default:
        out += character;
    }
  }
  return out;
}

