export interface AuthEnv {
  DB: D1Database;
  BETTER_AUTH_SECRET: string;
  MIGRATION_SECRET?: string;
  BETTER_AUTH_URL: string;
  PUBLIC_GAME_URL: string;
  BETTER_AUTH_TRUSTED_ORIGINS?: string;
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  GITHUB_CLIENT_ID?: string;
  GITHUB_CLIENT_SECRET?: string;
}

export type CliOAuthProvider = "google" | "github";

function configuredSecret(value: string | undefined): string | undefined {
  const trimmed = value?.trim();
  return trimmed || undefined;
}

export function providerCredentials(
  env: AuthEnv,
  provider: CliOAuthProvider,
): { clientId: string; clientSecret: string } | null {
  const clientId = configuredSecret(
    provider === "google" ? env.GOOGLE_CLIENT_ID : env.GITHUB_CLIENT_ID,
  );
  const clientSecret = configuredSecret(
    provider === "google" ? env.GOOGLE_CLIENT_SECRET : env.GITHUB_CLIENT_SECRET,
  );
  if (!clientId || !clientSecret) return null;
  return { clientId, clientSecret };
}

