import { getMigrations } from "better-auth/db/migration";
import { createAuth, providerCredentials, trustedOrigins, type AuthEnv, type CliOAuthProvider } from "./auth";
import { handoffRedirectPage, handoffUnauthorizedPage } from "./handoff-page";

const SESSION_TOKEN_COOKIE = "better-auth.session_token";

function trustedCliNext(value: string | null): URL | null {
  if (!value) return null;
  try {
    const next = new URL(value);
    if (next.protocol !== "http:") return null;
    if (next.hostname !== "127.0.0.1" && next.hostname !== "localhost") return null;
    return next;
  } catch {
    return null;
  }
}

function cookieValue(header: string | null, name: string): string | undefined {
  if (!header) return undefined;
  for (const part of header.split(";")) {
    const trimmed = part.trim();
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    if (trimmed.slice(0, eq) === name) return trimmed.slice(eq + 1);
  }
  return undefined;
}

function jsonError(status: number, error: string): Response {
  return Response.json({ error }, { status });
}

function htmlPage(status: number, body: string, extra: HeadersInit = {}): Response {
  return new Response(body, {
    status,
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-store",
      "referrer-policy": "no-referrer",
      ...extra,
    },
  });
}

function appendToken(next: URL, token: string): string {
  const joiner = next.search ? "&" : "?";
  return `${next.href}${joiner}token=${token}`;
}

async function handleCliHandoff(request: Request, env: AuthEnv): Promise<Response> {
  const url = new URL(request.url);
  const next = trustedCliNext(url.searchParams.get("next"));
  if (!next) return jsonError(400, "Invalid next URL");

  const auth = createAuth(env);
  const session = await auth.api.getSession({ headers: request.headers });
  const token = cookieValue(request.headers.get("cookie"), SESSION_TOKEN_COOKIE);
  if (!session?.user || !token) {
    return htmlPage(401, handoffUnauthorizedPage());
  }

  const target = appendToken(next, token);
  return htmlPage(200, handoffRedirectPage(target));
}

async function handleCliOAuth(request: Request, env: AuthEnv): Promise<Response> {
  const url = new URL(request.url);
  const provider = url.searchParams.get("provider");
  if (provider !== "google" && provider !== "github") {
    return jsonError(400, "Unsupported provider");
  }

  const next = trustedCliNext(url.searchParams.get("next"));
  if (!next) return jsonError(400, "Invalid next URL");

  if (!providerCredentials(env, provider as CliOAuthProvider)) {
    return jsonError(503, `${provider} sign-in is not configured.`);
  }

  const origin = url.origin;
  const handoffUrl = `${origin}/cli/handoff?${new URLSearchParams({ next: next.href })}`;
  const signInRequest = new Request(new URL("/api/auth/sign-in/social", origin), {
    method: "POST",
    headers: {
      "content-type": "application/json",
      origin,
      cookie: request.headers.get("cookie") ?? "",
    },
    body: JSON.stringify({
      provider,
      callbackURL: handoffUrl,
      disableRedirect: true,
    }),
  });
  const signInResponse = await createAuth(env).handler(signInRequest);
  const setCookies = signInResponse.headers.getSetCookie();
  let payload: { url?: string } | null = null;
  try {
    payload = await signInResponse.json() as { url?: string };
  } catch {
    payload = null;
  }
  if (!payload?.url) {
    return jsonError(502, "Could not start sign-in.");
  }
  const headers = new Headers({ location: payload.url, "cache-control": "no-store" });
  for (const cookie of setCookies) headers.append("set-cookie", cookie);
  return new Response(null, { status: 302, headers });
}

