import { spawnSync } from "node:child_process";
import { chmodSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import type { AddressInfo } from "node:net";
import { homedir } from "node:os";
import { join } from "node:path";
import type { AuthMethod } from "./analytics/events.js";
import { escapeHtml, signInFailedPage, signedInPage } from "./auth-pages.js";
import { clearBackendSession, saveBackendSession } from "./sync/config.js";

const defaultAuthBaseUrl = "https://auth.runretroarcade.com";
const defaultOAuthCallbackPort = 3210;
const oauthCallbackTimeoutMs = 300_000;

export type { AuthUser, StoredSession };

export interface OAuthCallbackServer {
  readonly port: number;
  ready: Promise<void>;
  token: Promise<string>;
  close(): void;
}

export function isArcBundle(bundleId: string): boolean {
  const id = bundleId.toLowerCase();
  return id === "company.thebrowser.browser" || id === "company.thebrowser.dia";
}

function applescriptEscape(value: string): string {
  return value.replaceAll("\\", "\\\\").replaceAll('"', '\\"');
}

export function arcTabScript(bundleId: string, url: string): string {
  return `tell application id "${applescriptEscape(bundleId)}"
    activate
    if (count of windows) is 0 then
        make new window
    end if
    tell front window to make new tab with properties {URL:"${applescriptEscape(url)}"}
end tell`;
}

function parseDefaultHttpsHandler(plist: string): string | undefined {
  for (const block of plist.split("{")) {
    if (!block.includes("LSHandlerURLScheme = https;")) continue;
    const line = block.split("\n").find((entry) => entry.trimStart().startsWith("LSHandlerRoleAll = "));
    if (!line) continue;
    const value = line.trim().replace(/^LSHandlerRoleAll = /, "").replace(/;$/, "").replaceAll('"', "");
    if (value) return value;
  }
  return undefined;
}

function defaultHttpsHandler(): string | undefined {
  const result = spawnSync("defaults", ["read", "com.apple.LaunchServices/com.apple.launchservices.secure"], {
    encoding: "utf8",
  });
  if (result.status !== 0 || !result.stdout) return undefined;
  return parseDefaultHttpsHandler(result.stdout);
}

function runOpener(command: string, args: string[]): boolean {
  return spawnSync(command, args, { stdio: "ignore" }).status === 0;
}

function openBrowser(url: string): boolean {
  if (process.platform === "darwin") {
    const bundleId = defaultHttpsHandler();
    if (bundleId && isArcBundle(bundleId) && runOpener("osascript", ["-e", arcTabScript(bundleId, url)])) {
      return true;
    }
    return runOpener("open", [url]) || runOpener("open", ["-a", "Safari", url]);
  }
  if (process.platform === "win32") {
    return runOpener("cmd", ["/c", "start", "", url])
      || runOpener("rundll32", ["url.dll,FileProtocolHandler", url]);
  }
  return runOpener("xdg-open", [url])
    || runOpener("gio", ["open", url])
    || runOpener("x-www-browser", [url]);
}

function queryParam(query: string, key: string): string | undefined {
  for (const pair of query.split(/[&?]/)) {
    const eq = pair.indexOf("=");
    const name = eq === -1 ? pair : pair.slice(0, eq);
    if (name === key) {
      return (eq === -1 ? "" : pair.slice(eq + 1)).replaceAll("+", " ");
    }
  }
  return undefined;
}

function percentDecode(value: string): string {
  const bytes = Buffer.from(value, "latin1");
  const out: number[] = [];
  let index = 0;
  const hex = (byte: number): number | undefined => {
    if (byte >= 48 && byte <= 57) return byte - 48;
    if (byte >= 97 && byte <= 102) return byte - 97 + 10;
    if (byte >= 65 && byte <= 70) return byte - 65 + 10;
    return undefined;
  };
  while (index < bytes.length) {
    if (bytes[index] === 37 && index + 2 < bytes.length) {
      const high = hex(bytes[index + 1]!);
      const low = hex(bytes[index + 2]!);
      if (high !== undefined && low !== undefined) {
        out.push(high * 16 + low);
        index += 3;
        continue;
      }
    }
    out.push(bytes[index]!);
    index += 1;
  }
  return Buffer.from(out).toString("utf8");
}

function callbackFailure(query: string): { message: string; bodyReason: string } | undefined {
  const error = queryParam(query, "error");
  if (!error) return undefined;
  if (error === "access_denied") {
    const message = "Sign-in was cancelled before it finished.";
    return { message, bodyReason: message };
  }
  const description = queryParam(query, "error_description");
  const decoded = description ? percentDecode(description) : "";
  const message = decoded
    ? decoded
    : `The login page reported an error: ${percentDecode(error)}`;
  return { message, bodyReason: escapeHtml(message) };
}

function send(
  res: ServerResponse,
  status: number,
  contentType: string,
  body: string,
  extra: Record<string, string> = {},
): void {
  const payload = Buffer.from(body);
  res.writeHead(status, {
    "Content-Type": contentType,
    "Content-Length": payload.length,
    Connection: "close",
    ...extra,
  });
  res.end(payload);
}

export function startOAuthCallbackServer(port: number): OAuthCallbackServer {
  let boundPort = port;
  let settled = false;
  let resolveToken!: (token: string) => void;
  let rejectToken!: (error: Error) => void;
  const token = new Promise<string>((resolve, reject) => {
    resolveToken = resolve;
    rejectToken = reject;
  });

  const finish = (ok: string | Error, onSent: () => void): void => {
    if (settled) {
      onSent();
      return;
    }
    settled = true;
    onSent();
    if (ok instanceof Error) rejectToken(ok);
    else resolveToken(ok);
  };

  const server = createServer((req: IncomingMessage, res: ServerResponse) => {
    const urlPath = req.url ?? "/";
    const qIndex = urlPath.indexOf("?");
    const path = qIndex === -1 ? urlPath : urlPath.slice(0, qIndex);
    const query = qIndex === -1 ? "" : urlPath.slice(qIndex + 1);

    if (path === "/auth/ping") {
      send(res, 200, "text/plain; charset=utf-8", "ok");
      return;
    }
    if (path !== "/auth/callback") {
      send(res, 404, "text/plain; charset=utf-8", "not found");
      return;
    }

    const cacheHeaders = {
      "Cache-Control": "no-store",
      "Referrer-Policy": "no-referrer",
    };
    const failure = callbackFailure(query);
    if (failure) {
      const status = 400;
      send(res, status, "text/html; charset=utf-8", signInFailedPage(failure.bodyReason), cacheHeaders);
      finish(new Error(failure.message), () => {});
      return;
    }
    const received = queryParam(query, "token");
    if (received) {
      send(res, 200, "text/html; charset=utf-8", signedInPage(), cacheHeaders);
      finish(received, () => {});
      return;
    }
    const reason = "The login page came back without a session token.";
    send(res, 400, "text/html; charset=utf-8", signInFailedPage(escapeHtml(reason)), cacheHeaders);
    finish(new Error(reason), () => {});
  });

  const ready = new Promise<void>((resolve, reject) => {
    let retried = false;
    const onListening = () => {
      server.off("error", onError);
      const address = server.address();
      if (!address || typeof address === "string") {
        reject(new Error("Could not start the sign-in listener."));
        return;
      }
      boundPort = (address as AddressInfo).port;
      resolve();
    };
    const onError = (error: NodeJS.ErrnoException) => {
      if (!retried && error.code === "EADDRINUSE") {
        retried = true;
        server.listen(0, "127.0.0.1");
        return;
      }
      server.off("listening", onListening);
      server.off("error", onError);
      reject(error);
    };
    server.on("error", onError);
    server.once("listening", onListening);
    server.listen(port, "127.0.0.1");
  });

  return {
    get port() {
      return boundPort;
    },
    ready,
    token,
    close() {
      server.close();
    },
  };
}

