test("oauth callback server pings, falls back when the port is busy, and reads a glued token", async () => {
  const blocker = createServer();
  await new Promise<void>((resolve) => blocker.listen(0, "127.0.0.1", resolve));
  const busyPort = (blocker.address() as AddressInfo).port;
  const callback = startOAuthCallbackServer(busyPort);
  try {
    await callback.ready;
    expect(callback.port).not.toBe(busyPort);

    const ping = await fetch(`http://127.0.0.1:${callback.port}/auth/ping`);
    expect(ping.status).toBe(200);
    expect(await ping.text()).toBe("ok");

    const pending = callback.token;
    const response = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=nonce?token=raw-session`,
    );
    expect(response.status).toBe(200);
    expect(response.headers.get("cache-control")).toBe("no-store");
    expect(await pending).toBe("raw-session");
  } finally {
    callback.close();
    await new Promise<void>((resolve) => blocker.close(() => resolve()));
  }
});

