import { env } from "cloudflare:workers";
import { expect, test } from "vitest";
import type { AuthEnv } from "../src/auth";
import worker from "../src/index";

const workerEnv = env as AuthEnv;

function request(path: string, init?: RequestInit): Promise<Response> {
  return worker.fetch(new Request(`https://auth.example${path}`, init), workerEnv);
}

test("cli handoff rejects a next target that is not a local http url before touching the session", async () => {
  const cookie = { headers: { cookie: "better-auth.session_token=stolen" } };
  const rejected = [
    "/cli/handoff?next=https://127.0.0.1:3210/auth/callback",
    "/cli/handoff?next=http://example.com/auth/callback",
    "/cli/handoff?next=http://127.0.0.1.attacker/auth/callback",
    "/cli/handoff",
  ];
  for (const path of rejected) {
    const response = await request(path, cookie);
    expect(response.status).toBe(400);
  }
});

test("cli handoff answers 401 with oauth guidance when there is no session", async () => {
  const response = await request("/cli/handoff?next=http://127.0.0.1:3210/auth/callback");
  expect(response.status).toBe(401);
  expect(await response.text()).toMatch(/oauth/i);
});

test("cli oauth rejects any provider other than google or github", async () => {
  const response = await request(
    "/cli/oauth?provider=twitter&next=http://127.0.0.1:3210/auth/callback",
  );
  expect(response.status).toBe(400);
});

test("cli oauth refuses a remote next url before starting sign-in", async () => {
  const response = await request(
    "/cli/oauth?provider=google&next=https://evil.example/steal",
  );
  expect(response.status).toBe(400);
});

test("cli oauth returns 503 when the provider is not configured", async () => {
  const response = await request(
    "/cli/oauth?provider=google&next=http://127.0.0.1:3210/auth/callback",
  );
  expect(response.status).toBe(503);
});

test("cli oauth redirects onward once credentials are configured", async () => {
  const configured = {
