  const { getMigrations } = await import("better-auth/db/migration");
  const { createAuth } = await import("../src/auth");
  const auth = createAuth(workerEnv);
  const { runMigrations } = await getMigrations(auth.options);
  await runMigrations();

  const signUp = await request("/api/auth/sign-up/email", {
    method: "POST",
    headers: {
      "content-type": "application/json",
      origin: workerEnv.BETTER_AUTH_URL,
    },
    body: JSON.stringify({
      email: `oauth-${crypto.randomUUID()}@example.com`,
      password: "password-password",
      name: "OAuth",
    }),
  });
  expect(signUp.ok).toBe(true);
  const setCookie = signUp.headers.getSetCookie().join("; ");
  const cookieMatch = setCookie.match(/(?:^|;\s*)(?:__Secure-)?better-auth\.session_token=([^;]+)/);
  expect(cookieMatch?.[1]).toBeTruthy();
  const token = cookieMatch![1]!;

  const next = "http://127.0.0.1:3210/auth/callback?state=nonce";
  const response = await request(`/cli/handoff?${new URLSearchParams({ next })}`, {
    headers: { cookie: `better-auth.session_token=${token}` },
  });
  expect(response.status).toBe(200);
  expect(response.headers.get("cache-control")).toBe("no-store");
  const body = await response.text();
  const expected = `${next}&token=${token}`;
  expect(body).toContain(expected);
});

